package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

@RunWith(JUnit4.class)
public class Node_absUrl_TriageGen1Test {

    @Test
    public void testAbsUrl_EmptyAttributeKey() {
        Node node = new Node("https://example.com", new Attributes());
        node.absUrl("");
        assertTrue(node.absUrl("").isEmpty());
    }

    @Test
    public void testAbsUrl_NullAttributeKey() {
        Node node = new Node("https://example.com", new Attributes());
        node.absUrl(null);
        assertTrue(node.absUrl(null).isEmpty());
    }

    @Test
    public void testAbsUrl_RelativeUrl() {
        Node node = new Node("https://example.com", new Attributes());
        String relUrl = "path/to/file";
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, relUrl);
        assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
    }

    @Test
    public void testAbsUrl_RelativeUrlWithQuery() {
        Node node = new Node("https://example.com", new Attributes());
        String relUrl = "path/to/file?query=param";
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, relUrl);
        assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
    }

    @Test
    public void testAbsUrl_RelativeUrlWithFragment() {
        Node node = new Node("https://example.com", new Attributes());
        String relUrl = "path/to/file#fragment";
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, relUrl);
        assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
    }

    @Test
    public void testAbsUrl_UnsuitableBase() {
        Node node = new Node("unsuitable base", new Attributes());
        String relUrl = "path/to/file";
        try {
            URL base = new URL(node.baseUri());
            URL abs = new URL(base, relUrl);
            assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
        } catch (MalformedURLException e) {
            assertTrue(node.absUrl(relUrl).isEmpty());
        }
    }

    @Test
    public void testAbsUrl_UseRelativeUrlWhenBaseIsInvalid() {
        Node node = new Node("invalid base", new Attributes());
        String relUrl = "path/to/file";
        try {
            URL base = new URL(node.baseUri());
            URL abs = new URL(base, relUrl);
            assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
        } catch (MalformedURLException e) {
            assertTrue(node.absUrl(relUrl).isEmpty());
        }
    }

    @Test
    public void testAbsUrl_RelativeUrlWithoutScheme() {
        Node node = new Node("https://example.com", new Attributes());
        String relUrl = "path/to/file";
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, relUrl);
        assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
    }

    @Test
    public void testAbsUrl_RelativeUrlWithoutPath() {
        Node node = new Node("https://example.com/path", new Attributes());
        String relUrl = "to/file";
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, relUrl);
        assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
    }

    @Test
    public void testAbsUrl_RelativeUrlWithoutQuery() {
        Node node = new Node("https://example.com/path", new Attributes());
        String relUrl = "to/file";
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, relUrl);
        assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
    }

    @Test
    public void testAbsUrl_RelativeUrlWithoutFragment() {
        Node node = new Node("https://example.com/path", new Attributes());
        String relUrl = "to/file";
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, relUrl);
        assertEquals(abs.toExternalForm(), node.absUrl(relUrl));
    }

    @Test
    public void testAbsUrl_NoAttr() {
        Node node = new Node("https://example.com", new Attributes());
        node.hasAttr("attr");
        assertTrue(node.absUrl("attr").isEmpty());
    }

    @Test
    public void testAbsUrl_ValidAttr() {
        Node node = new Node("https://example.com", new Attributes());
        node.attr("attr", "value");
        URL base = new URL(node.baseUri());
        URL abs = new URL(base, "value");
        assertEquals(abs.toExternalForm(), node.absUrl("attr"));
    }
}
